-- Lineup Explorer ↔ RaveFAM integration, Phase 0.
-- Lineups for the 21 festivals added in 20260927000000 (they had none).
-- Data comes from each page's ACTS array via
-- _ops/aggregate-artists/build-artists-seed.mjs (b2b entries split, names
-- canonicalized), stored here as compact JSON.
--
-- Scope is deliberately limited to those 21 festivals. The other 13 explorer
-- festivals were seeded earlier with a different night/note format (e.g. no
-- day on EDC Orlando rows, "b2b set; b2b set" notes); night and note are part
-- of the appearances unique key, so re-syncing them would add duplicate rows
-- rather than update. Their lineups are left as they are.
--
-- Artists: inserted only if missing (existing rows untouched).
-- Appearances: artist matched on name_lower = lower(name), festival on slug.

insert into public.artists (name, genres)
select e->>0, array(select jsonb_array_elements_text(e->1))
